{
  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])

    # Build maps
    node_by_id = {}
    children = {}
    for node in nodes:
        nid = node['id']
        node_by_id[nid] = node
        children[nid] = []
    for node in nodes:
        parent = node['parent']
        if parent is not None:
            children[parent].append(node['id'])

    remaining = set(node_by_id.keys())
    removal_order = []

    def get_subtree(nid, remaining_set):
        """Return set of all nodes in subtree of nid that are in remaining_set."""
        subtree = set()
        stack = [nid]
        while stack:
            cur = stack.pop()
            if cur in subtree:
                continue
            subtree.add(cur)
            for child in children[cur]:
                if child in remaining_set:
                    stack.append(child)
        return subtree

    candidates = sorted(node_by_id.keys(), key=lambda nid: (-node_by_id[nid]['depth'], nid))

    for nid in candidates:
        if nid not in remaining:
            continue
        node = node_by_id[nid]
        if not node['removable']:
            continue
        if node['symbol'] in required_symbols:
            continue
        # Check for retained children
        has_retained_child = any(child in remaining for child in children[nid])
        if has_retained_child:
            continue
        # Compute the subtree that would be removed
        subtree = get_subtree(nid, remaining)
        new_remaining = remaining - subtree
        # Verify all required symbols still exist
        req_met = all(
            any(node_by_id[n]['symbol'] == sym for n in new_remaining)
            for sym in required_symbols
        )
        if not req_met:
            continue
        # Perform removal
        remaining = new_remaining
        removal_order.append(nid)

    retained = sorted(remaining)
    return {"removed_node_ids": removal_order, "retained_node_ids": retained}"
}
